passing_property:
// No clock or reset signals are present in the RTL

    // The logic is purely combinational as there are no sequential elements

    // Key signals and interfaces:
    // Y, A1, A2, B1_N are inputs
    // VPWR, VGND, VPB, VNB are power and ground signals

    // Functional behaviors:
    // Y is the output of a combinational logic circuit

    // Combinational logic behavior:
    // Y = !B1_N && (A2 || A1)

    // Assertion for the combinational logic behavior
    comb_logic: assert property (
        @(posedge VPWR) disable iff (VGND) (Y == (!B1_N && (A2 || A1)))
    ) else $error("Combinational logic behavior violated");

// The logic is purely combinational as there are no sequential elements.

    // The output Y is the result of a NOR operation on inputs A, B, C, and D.
    // NOR operation: Y = ~(A | B | C | D)
    combinational_logic: assert property (
        @(posedge VPWR) disable iff (VGND) (Y == ~(A | B | C | D))
    );

// Combinational logic: SUM and Cout are determined by A, B, and Cin
  // Clocked assertions to ensure the combinational logic is correct
  // at the rising edge of the clock

  // SUM is the XOR of A, B, and Cin
  sum_correct: assert property (
    @(posedge CLK) disable iff (!CLK) Sum == (A ^ B ^ Cin)
  );

// Cout is the OR of the ANDs of A and B, A and Cin, and B and Cin
  cout_correct: assert property (
    @(posedge CLK) disable iff (!CLK) Cout == ((A & B) | (A & Cin) | (B & Cin))
  );

///// Counter reset /////
    // At reset, the counter must be driven to 0.
    reset_count: assert property (
        @(posedge clk) disable iff (!reset) (reset |-> count == 4'b0)
    );

///// Counter increment /////
    // The counter must increment by 1 on each clock cycle when reset is low.
    increment_count: assert property (
        @(posedge clk) disable iff (!reset) (!reset |-> count == count + 1)
    );

///// Output toggle /////
    // The output must toggle on each clock cycle when reset is low.
    toggle_out: assert property (
        @(posedge clk) disable iff (!reset) (!reset |-> out == ~out)
    );

///// Register behavior /////
    // Register r_bus_addr_out should hold the value of w_bus_addr_in on the positive edge of w_clock.
    register_update: assert property (
        @(posedge w_clock) disable iff (!w_reset) r_bus_addr_out == w_bus_addr_in
    );

// Register r_bus_addr_out should be reset to 0 on the positive edge of w_clock when w_reset is asserted.
    register_reset: assert property (
        @(posedge w_clock) disable iff (!w_reset) (w_reset == 1'b1) |-> r_bus_addr_out == 8'b0
    );

// Ensure that the output is consistent with the input and enable
    output_consistency_check: assert property (
        @(posedge clk) disable iff (!rst_n) (ena |-> (out == (16'b1 << in) | 16'b1))
    );

// Ensure that the output is consistent with the input and enable
    output_consistency_with_enable_check: assert property (
        @(posedge clk) disable iff (!rst_n) (ena |-> (out == (16'b1 << in) | 16'b1))
    );

///// Clock gating logic /////
    // data_out should only change when en is HIGH.
    clock_gating_1: assert property (
        @(posedge clk) disable iff (!clk) $changed(data_out) |-> en == 1'b1
    );

// data_out should be LOW when en is LOW.
    clock_gating_2: assert property (
        @(posedge clk) disable iff (!clk) (en == 1'b0) |-> data_out == 1'b0
    );

// XOR logic must be correct
    xor_logic: assert property (
        @(posedge CLK) disable iff (!CLK) Sgn_Info == (Sgn_X ^ Sgn_Y)
    );

// COUT is the result of ANDing A and B
    and_result: assert property (
        @(posedge CLK) disable iff (!CLK) (COUT == (A & B))
    );

// SUM is the result of XORing A and B
    xor_result: assert property (
        @(posedge CLK) disable iff (!CLK) (SUM == (A ^ B))
    );

///// Register reset /////
    // At reset assertion, the register must be driven to 0.
    reset_register: assert property (
        @(posedge clk) disable iff (!reset) register == 4'b0000
    );

///// Parallel load /////
    // When parallel_load is asserted, the register must be loaded with parallel_input.
    parallel_load_check: assert property (
        @(posedge clk) disable iff (!reset) (parallel_load |-> register == parallel_input)
    );

///// Shift left /////
    // When shift_left is asserted, the register must shift left by one position.
    shift_left_check: assert property (
        @(posedge clk) disable iff (!reset) (shift_left |-> register == {register[2:0], 1'b0})
    );

///// Shift right /////
    // When shift_right is asserted, the register must shift right by one position.
    shift_right_check: assert property (
        @(posedge clk) disable iff (!reset) (shift_right |-> register == {1'b0, register[3:1]})
    );

///// Exclusive control /////
    // Only one of parallel_load, shift_left, or shift_right can be asserted at a time.
    exclusive_control: assert property (
        @(posedge clk) disable iff (!reset) !(parallel_load && shift_left) && !(parallel_load && shift_right) && !(shift_left && shift_right)
    );

///// Device reset /////
    // At reset assertion, pwm_out must be LOW.
    reset: assert property (
        @(posedge clk) !rst_n |-> (pwm_out == 1'b0)
    );

///// Sequential logic behavior /////
    // FSM_sequential_state_reg_reg should be reset to 2'b00 when FSM_selector_C is HIGH.
    reset_to_zero: assert property (
        @(posedge clk_IBUF_BUFG) disable iff (!clk_IBUF_BUFG) FSM_selector_C |-> (FSM_sequential_state_reg_reg == 2'b00)
    );

// FSM_sequential_state_reg_reg should increment by AR when FSM_selector_C is LOW.
    increment_on_ar: assert property (
        @(posedge clk_IBUF_BUFG) disable iff (!clk_IBUF_BUFG) !FSM_selector_C |-> FSM_sequential_state_reg_reg == FSM_sequential_state_reg_reg + AR
    );

// The logic is purely combinational as it only uses assign statements.

    // The output Y is the negation of the OR of A, B, C, and D_N.
    combinational_logic: assert property (
        @(posedge VPB) disable iff (!VGND) Y == ~(A | B | C | D_N)
    );

// ctrl_bits_for_mux should always be within the valid range [0, 7].
    ctrl_bits_for_mux_range: assert property (
        @(posedge clk) disable iff (!rst_n) (ctrl_bits_for_mux >= 3'b000) && (ctrl_bits_for_mux <= 3'b111)
    );

// td_mode should always be one of the valid values [0, 15].
    td_mode_range: assert property (
        @(posedge clk) disable iff (!rst_n) (td_mode >= 4'b0000) && (td_mode <= 4'b1111)
    );

// ctrl_bits_for_mux should not change when td_mode is changing.
    ctrl_bits_for_mux_stable: assert property (
        @(posedge clk) disable iff (!rst_n) (ctrl_bits_for_mux == ctrl_bits_for_mux)
    );

// td_mode should not change when ctrl_bits_for_mux is changing.
    td_mode_stable: assert property (
        @(posedge clk) disable iff (!rst_n) (td_mode == td_mode)
    );

// The OR4B module has combinational logic, so we will use @(posedge CLK) for assertions.

    // The output X is the result of the OR operation on A, B, C, and the inverted D_N.
    // The OR operation is performed on the inputs A, B, C, and the inverted D_N.
    // The output X is the result of the OR operation.
    or4b_output: assert property (
        @(posedge CLK) disable iff (!CLK) (X == (A | B | C | ~D_N))
    );

// Sequential logic: o_dataout and o_dataout_valid are driven by the clock
    // Combinational logic: o_dataout and o_dataout_valid are driven by i_settings, i_register_settings, and i_datain

    // o_dataout should be equal to i_register_settings when i_settings is high
    bypass_reg_1: assert property (
        @(posedge clock) disable iff (!resetn) (i_settings == 1'b1) |-> (o_dataout == i_register_settings)
    );

// o_dataout should be equal to i_datain when i_settings is low
    bypass_reg_2: assert property (
        @(posedge clock) disable iff (!resetn) (i_settings == 1'b0) |-> (o_dataout == i_datain)
    );

// o_dataout_valid should be equal to i_datain_valid
    bypass_reg_3: assert property (
        @(posedge clock) disable iff (!resetn) (o_dataout_valid == i_datain_valid)
    );

// o_datain_stall should be equal to i_dataout_stall
    bypass_reg_4: assert property (
        @(posedge clock) disable iff (!resetn) (o_datain_stall == i_dataout_stall)
    );

// i_datain_valid should not be high when i_dataout_stall is high
    bypass_reg_5: assert property (
        @(posedge clock) disable iff (!resetn) (i_dataout_stall == 1'b1) |-> (i_datain_valid == 1'b0)
    );

// i_settings should not be high when i_dataout_stall is high
    bypass_reg_6: assert property (
        @(posedge clock) disable iff (!resetn) (i_dataout_stall == 1'b1) |-> (i_settings == 1'b0)
    );

// i_register_settings should not be used when i_dataout_stall is high
    bypass_reg_7: assert property (
        @(posedge clock) disable iff (!resetn) (i_dataout_stall == 1'b1) |-> (i_register_settings == 32'b0)
    );

// i_datain should not be used when i_dataout_stall is high
    bypass_reg_8: assert property (
        @(posedge clock) disable iff (!resetn) (i_dataout_stall == 1'b1) |-> (i_datain == 32'b0)
    );

// i_datain_valid should not be high when o_datain_stall is high
    bypass_reg_9: assert property (
        @(posedge clock) disable iff (!resetn) (o_datain_stall == 1'b1) |-> (i_datain_valid == 1'b0)
    );

// i_settings should not be high when o_datain_stall is high
    bypass_reg_10: assert property (
        @(posedge clock) disable iff (!resetn) (o_datain_stall == 1'b1) |-> (i_settings == 1'b0)
    );

// Reset behavior: count should be 0 at reset
    reset: assert property (
        @(posedge clk) disable iff (!rst) count == 3'b0
    );

// Counting behavior: count should increment by 1 on each clock cycle
    counting: assert property (
        @(posedge clk) disable iff (!rst) count == count + 1
    );

// Q should not change when CLR is HIGH.
    no_change_on_reset: assert property (
        @(posedge CLK) CLR |-> Q == Q
    );

// Q_next should not change when CLR is HIGH.
    next_no_change_on_reset: assert property (
        @(posedge CLK) CLR |-> Q_next == Q_next
    );

// Q should not change when LOAD is LOW and CLR is LOW.
    no_change_on_load: assert property (
        @(posedge CLK) disable iff (!CLR) (LOAD == 1'b0) |-> Q == Q
    );

// Q_next should not change when LOAD is LOW and CLR is LOW.
    next_no_change_on_load: assert property (
        @(posedge CLK) disable iff (!CLR) (LOAD == 1'b0) |-> Q_next == Q_next
    );

// op_reg can only transition from 1 to 0 when clr is HIGH.
  transition_2: assert property (
    @(posedge clk) disable iff (!clr) $fell(op_reg) |-> (clr == 1'b1)
  );

// Reset behavior: Q and QN should be 0 and 1 respectively when RST is active
  reset: assert property (
    @(posedge CLK) disable iff (!RST) (Q == 1'b0) && (QN == 1'b1)
  );

// Reset behavior: count should be 0 at reset
  reset_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count == 4'b0)
  );

// Enable behavior: count should increment when enable is high
  enable_behavior: assert property (
    @(posedge clk) disable iff (!reset) (enable |-> count == count + 1)
  );

// Disable behavior: count should not increment when enable is low
  disable_behavior: assert property (
    @(posedge clk) disable iff (!reset) (!enable |-> count == count)
  );

// Count range behavior: count should not exceed 4'b1111
  count_range_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count <= 4'b1111)
  );

// Count should not wrap around from 4'b1111 to 4'b0000
  count_wrap_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 4'b0000 |-> count != 4'b1111)
  );

// Count should not be negative
  count_negative_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count >= 4'b0000)
  );

// Count should not be greater than 4 bits
  count_bits_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count < 5'b10000)
  );

// Count should not be equal to 4'b10000
  count_10000_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b10000)
  );

// Count should not be equal to 4'b10001
  count_10001_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b10001)
  );

// Count should not be equal to 4'b10010
  count_10010_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b10010)
  );

// Count should not be equal to 4'b10011
  count_10011_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b10011)
  );

// Count should not be equal to 4'b10100
  count_10100_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b10100)
  );

// Count should not be equal to 4'b10101
  count_10101_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b10101)
  );

// Count should not be equal to 4'b10110
  count_10110_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b10110)
  );

// Count should not be equal to 4'b10111
  count_10111_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b10111)
  );

// Count should not be equal to 4'b11000
  count_11000_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b11000)
  );

// Count should not be equal to 4'b11001
  count_11001_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b11001)
  );

// Count should not be equal to 4'b11010
  count_11010_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b11010)
  );

// Count should not be equal to 4'b11011
  count_11011_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b11011)
  );

// Count should not be equal to 4'b11100
  count_11100_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b11100)
  );

// Count should not be equal to 4'b11101
  count_11101_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b11101)
  );

// Count should not be equal to 4'b11110
  count_11110_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b11110)
  );

// Count should not be equal to 4'b11111
  count_11111_behavior: assert property (
    @(posedge clk) disable iff (!reset) (count != 5'b11111)
  );

// Reset behavior: count should be 0 after reset
  reset_behavior: assert property (
    @(posedge clk) disable iff (!rst) count == 4'b0000
  );

// Counting behavior: count should increment by 1 on each clock edge
  counting_behavior: assert property (
    @(posedge clk) disable iff (!rst) count == count + 1
  );

///// Reset behavior /////
    // At reset, control_o and pc_op must be driven to 0.
    reset: assert property (
        @(posedge clk) disable iff (!rst) (rst |-> (control_o == 8'b0) && (pc_op == 2'b0))
    );

///// Enable behavior /////
    // When en is high, control_o[0] should be equal to en_mem.
    enable_en_mem: assert property (
        @(posedge clk) disable iff (!rst) (en |-> (control_o[0] == en_mem))
    );

// When en is high, control_o[1] should be equal to should_branch.
    enable_should_branch: assert property (
        @(posedge clk) disable iff (!rst) (en |-> (control_o[1] == should_branch))
    );

// When en is high, control_o[2] should be equal to imm.
    enable_imm: assert property (
        @(posedge clk) disable iff (!rst) (en |-> (control_o[2] == imm))
    );

///// Opcode generation /////
    // When imm is high, pc_op should be 2'b10 (Bitwise AND).
    opcode_and: assert property (
        @(posedge clk) disable iff (!rst) (imm |-> (pc_op == 2'b10))
    );

// When imm is low, pc_op should be 2'b00 (Add).
    opcode_add: assert property (
        @(posedge clk) disable iff (!rst) (!imm |-> (pc_op == 2'b00))
    );

///// Memory wait behavior /////
    // mem_wait should not affect control_o or pc_op directly.
    mem_wait_behavior: assert property (
        @(posedge clk) disable iff (!rst) (mem_wait |-> (control_o == control_o) && (pc_op == pc_op))
    );

// Binary to Gray conversion on load
    binary_to_gray_conversion: assert property (
        @(posedge load) disable iff (!load) (out == (in >> 1) ^ in)
    );

// Valid signal should be high only when load is high
    valid_signal: assert property (
        @(posedge load) disable iff (!load) (valid == 1'b1)
    );

// Reset behavior: count should be 0 at reset
  reset_behavior: assert property (
    @(posedge clk) disable iff (!rst) (count == 4'b0)
  );

// Counting behavior: count should increment by 1 on each clock edge
  counting_behavior: assert property (
    @(posedge clk) disable iff (!rst) (count == 4'b1111) |-> count == 4'b0000
  );

// Ripple adder logic is combinational, but we will use @(posedge clk) for assertions.

    // Sum calculation is correct for each bit position
    bit_calculation: assert property (
        @(posedge clk) $rose(sum) |-> (sum == a + b)
    );

// Sum calculation is correct for each bit position
    bit_calculation_2: assert property (
        @(posedge clk) $rose(sum) |-> (sum == a + b)
    );

// Sum calculation is correct for each bit position
    bit_calculation_3: assert property (
        @(posedge clk) $rose(sum) |-> (sum == a + b)
    );

// Sum calculation is correct for each bit position
    bit_calculation_4: assert property (
        @(posedge clk) $rose(sum) |-> (sum == a + b)
    );

// Sum calculation is correct for each bit position
    bit_calculation_5: assert property (
        @(posedge clk) $rose(sum) |-> (sum == a + b)
    );

// Sum calculation is correct for each bit position
    bit_calculation_6: assert property (
        @(posedge clk) $rose(sum) |-> (sum == a + b)
    );

// Sum calculation is correct for each bit position
    bit_calculation_7: assert property (
        @(posedge clk) $rose(sum) |-> (sum == a + b)
    );

// Sum calculation is correct for each bit position
    bit_calculation_8: assert property (
        @(posedge clk) $rose(sum) |-> (sum == a + b)
    );

// Reset behavior: count should be 0 at reset
    reset_behavior: assert property (
        @(posedge clk) disable iff (!reset) (count == 4'b0)
    );

// Counting behavior: count should increment by 1 on each clock edge
    counting_behavior: assert property (
        @(posedge clk) disable iff (!reset) (count == 4'b1111) |-> count == 4'b0000
    );

// Shift direction must be either 0 (left) or 1 (right)
    direction_check: assert property (
        @(posedge clk) disable iff (!rst_n) (dir == 0 || dir == 1)
    );

// Shift amount must be within the valid range [0, 15]
    shift_amount_check: assert property (
        @(posedge clk) disable iff (!rst_n) (shift >= 4'b0000 && shift <= 4'b1111)
    );

///// Register behavior /////
    // Register reg_0x1F should be reset to 0x00 on reset.
    reset_reg_0x1F: assert property (
        @(posedge clk) disable iff (!reset) reg_0x1F == 8'h00
    );

// Register reg_0x1F should be updated with in_data when wenb is 0.
    update_reg_0x1F: assert property (
        @(posedge clk) disable iff (!reset) (wenb == 1'b0) |-> reg_0x1F == in_data
    );

// Register reg_0x1F should remain unchanged when wenb is 1.
    no_update_reg_0x1F: assert property (
        @(posedge clk) disable iff (!reset) (wenb == 1'b1) |-> reg_0x1F == reg_0x1F
    );

///// Register behavior /////
    // Q_reg should only change on the rising edge of clk or on reset.
    reg_change: assert property (
        @(posedge clk) disable iff (!reset) Q_reg !== Q_reg
    );

// Q_reg should be loaded with data_in when load is asserted.
    load_behavior: assert property (
        @(posedge clk) disable iff (!reset) (load == 1'b1) |-> (Q_reg == data_in)
    );

// Q_reg should be reset to 0 when reset is asserted.
    reset_behavior: assert property (
        @(posedge clk) disable iff (!reset) reset |-> (Q_reg == 4'b0)
    );

// Q should always reflect the current value of Q_reg.
    q_output: assert property (
        @(posedge clk) disable iff (!reset) Q == Q_reg
    );

// Q_reg should not change when neither load nor reset is asserted.
    no_change: assert property (
        @(posedge clk) disable iff (!reset) (!load && !reset) |-> Q_reg == Q_reg
    );

// Q_reg should not change when reset is asserted.
    reset_no_change: assert property (
        @(posedge clk) disable iff (!reset) reset |-> Q_reg == Q_reg
    );

// Q_reg should not change when load is asserted but reset is not.
    load_no_change: assert property (
        @(posedge clk) disable iff (!reset) (load && !reset) |-> Q_reg == Q_reg
    );

// Q_reg should not change when data_in is not changing.
    data_in_no_change: assert property (
        @(posedge clk) disable iff (!reset) data_in == data_in |-> Q_reg == Q_reg
    );

// Q_reg should not change when clk is not rising edge.
    clk_no_change: assert property (
        @(posedge clk) disable iff (!reset) clk |-> Q_reg == Q_reg
    );

// Q_reg should not change when load and reset are both asserted.
    load_reset_no_change: assert property (
        @(posedge clk) disable iff (!reset) (load && reset) |-> Q_reg == Q_reg
    );

///// Load behavior /////
    // Q can only transition when load is HIGH.
    load_behavior: assert property (
        @(posedge clk) disable iff (!clk) $rose(load) |-> Q == input_data
    );

///// Up/Down behavior /////
    // Q increments when up_down is HIGH and load is LOW.
    up_behavior: assert property (
        @(posedge clk) disable iff (!clk) (up_down == 1'b1) && (load == 1'b0) |-> Q == Q + 1
    );

// Q decrements when up_down is LOW and load is LOW.
    down_behavior: assert property (
        @(posedge clk) disable iff (!clk) (up_down == 1'b0) && (load == 1'b0) |-> Q == Q - 1
    );

///// Sequential logic /////
    // Q should not change when load is LOW and up_down is LOW.
    no_change_behavior: assert property (
        @(posedge clk) disable iff (!clk) (load == 1'b0) && (up_down == 1'b0) |-> Q == Q
    );

// Reset behavior: COUNT should be 0 when RST is active
    reset: assert property (
        @(posedge clk) disable iff (!RST) COUNT == 4'b0000
    );

// Enable behavior: COUNT should increment when EN is high and RST is low
    enable: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b1) |-> COUNT == COUNT + 1
    );

// Synchronous reset behavior: COUNT should be 0 after a synchronous reset
    sync_reset: assert property (
        @(posedge clk) disable iff (!RST) RST |-> COUNT == 4'b0000
    );

// Asynchronous reset behavior: COUNT should be 0 after an asynchronous reset
    async_reset: assert property (
        @(posedge clk) disable iff (!RST) RST |-> COUNT == 4'b0000
    );

// COUNT should not exceed 4'b1111
    count_limit: assert property (
        @(posedge clk) disable iff (!RST) COUNT <= 4'b1111
    );

// COUNT should not be negative
    count_non_negative: assert property (
        @(posedge clk) disable iff (!RST) COUNT >= 4'b0000
    );

// COUNT should not wrap around
    count_wraparound: assert property (
        @(posedge clk) disable iff (!RST) (COUNT == 4'b1111) |-> COUNT + 1 == 4'b0000
    );

// COUNT should not decrement when EN is low
    count_no_decrement: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b0) |-> COUNT == COUNT
    );

// COUNT should not increment when RST is high
    count_no_increment_on_reset: assert property (
        @(posedge clk) disable iff (!RST) (RST == 1'b1) |-> COUNT == COUNT
    );

// COUNT should not be zero when EN is low and RST is low
    count_non_zero_when_en_low: assert property (
        @(posedge clk) disable iff (!RST) (EN == 1'b0) |-> COUNT != 4'b0000
    );

// COUNT should not be zero when RST is low
