    // Sum is correct for A[3] + B[3] + carry from third least significant bit
    most_significant_bit: assert property (
        @(posedge clk) $rose(A[3]) |-> (sum[3] == A[3] ^ B[3] ^ sum[2])
    );

///// Synchronous Reset Behavior /////
  // At reset, the counter should be driven to 0.
  reset_to_zero: assert property (
    @(posedge clk) disable iff (!reset) reset |-> count == 4'b0
  );

///// Load Behavior /////
  // When load is asserted, the counter should be loaded with data_in.
  load_behavior: assert property (
    @(posedge clk) disable iff (!reset) load |-> count == data_in
  );

///// Counting Behavior /////
  // When neither reset nor load is asserted, the counter should increment by 1.
  counting_behavior: assert property (
    @(posedge clk) disable iff (!reset) !(reset | load) |-> count == count + 4'b1
  );

// Reset behavior: All outputs should be 0 when reset is active
    reset_behavior: assert property (
        @(posedge shift_clk) disable iff (!reset) (reset |-> (q0 == 4'b0000) && (q1 == 4'b0000) && (q2 == 4'b0000) && (q3 == 4'b0000))
    );

// Shift behavior: Each output should shift to the next on the rising edge of shift_clk
    shift_behavior: assert property (
        @(posedge shift_clk) disable iff (!reset) (q0 == data_in) && (q1 == q0) && (q2 == q1) && (q3 == q2)
    );

// Reset behavior: out should be 0 at reset
  reset_behavior: assert property (
    @(posedge clk) disable iff (!reset) out == 4'b0
  );

// Load behavior: out should be the lower 4 bits of data when load is high
  load_behavior: assert property (
    @(posedge clk) disable iff (!reset) (load |-> out == data[3:0])
  );

// Select behavior: out should be {in[2:0], in[3]} when select is high
  select_behavior: assert property (
    @(posedge clk) disable iff (!reset) (select |-> out == {in[2:0], in[3]})
  );

// Default behavior: out should be {in[0], in[3:1]} when neither load nor select is high
  default_behavior: assert property (
    @(posedge clk) disable iff (!reset) (!(load | select) |-> out == {in[0], in[3:1]})
  );

// Reset behavior: count should be 0 after reset
    reset: assert property (
        @(posedge clk) disable iff (!rst) count == 4'b0000
    );

// Count should increment by 1 on each positive edge of clk, except when it reaches 9
    count_increment: assert property (
        @(posedge clk) disable iff (!rst) (count != 4'b1001) |-> count == count + 1
    );

// Count should wrap around to 0 when it reaches 9
    count_wrap: assert property (
        @(posedge clk) disable iff (!rst) count == 4'b1001 |-> count == 4'b0000
    );

// Ensure that gated_clk is only high when both src_clk and clk_en are high
    gated_clk_high: assert property (
        @(posedge src_clk) disable iff (!clk_en) gated_clk |-> (src_clk == 1'b1) && (clk_en == 1'b1)
    );

// Ensure that gated_clk is low when either src_clk or clk_en is low
    gated_clk_low: assert property (
        @(posedge src_clk) disable iff (!clk_en) gated_clk |-> (src_clk == 1'b0) || (clk_en == 1'b0)
    );

// Ensure that gated_clk is always low when clk_en is low
    gated_clk_when_clk_en_low: assert property (
        @(posedge src_clk) disable iff (!clk_en) gated_clk |-> (clk_en == 1'b0)
    );

// Ensure that gated_clk is always high when both src_clk and clk_en are high
    gated_clk_when_clk_en_high: assert property (
        @(posedge src_clk) disable iff (!clk_en) gated_clk |-> (src_clk == 1'b1) && (clk_en == 1'b1)
    );

// Ensure that gated_clk is stable when clk_en is high
    gated_clk_stable_when_clk_en_high: assert property (
        @(posedge src_clk) disable iff (!clk_en) $stable(gated_clk) |-> (clk_en == 1'b1)
    );

// Ensure that gated_clk is always low when src_clk is low
    gated_clk_when_src_clk_low: assert property (
        @(posedge src_clk) disable iff (!clk_en) gated_clk |-> (src_clk == 1'b0)
    );

// Ensure that gated_clk is always high when src_clk is high
    gated_clk_when_src_clk_high: assert property (
        @(posedge src_clk) disable iff (!clk_en) gated_clk |-> (src_clk == 1'b1)
    );

// Ensure that gated_clk is stable when src_clk is low
    gated_clk_stable_when_src_clk_low: assert property (
        @(posedge src_clk) disable iff (!clk_en) $stable(gated_clk) |-> (src_clk == 1'b0)
    );
